/**
 * The prize rows as SQL, generated from lib/giveaway/config.ts so the
 * database and the code cannot disagree about a prize.
 *
 * 0010's seed block is FROZEN: 0010 was applied to the live project on
 * 2026-11-03 and is never edited again. Prize changes since then ship as a
 * sync migration — an UPDATE of every env's giveaway_prizes rows to what
 * config computes — generated by prizeSyncSql(); config.test.mjs checks the
 * NEWEST sync migration against it (older ones, like 0013, are history).
 *
 * One prize per drawing (Ben, 2026-11-03): both of 0010's rows per slot
 * (version new_client / current_client) get the same prize.
 *
 * Pure.
 */

import { PRIZES, prizeDescription, prizeName, prizePractitionerCostUsd, prizeRetailUsd, prizeTaxFormRequired } from "./config";

export const SYNC_BEGIN = "-- BEGIN prize sync generated from lib/giveaway/config.ts (do not edit by hand; npm test checks it)";
export const SYNC_END = "-- END prize sync generated from lib/giveaway/config.ts";

const lit = (s: string) => `'${s.replace(/'/g, "''")}'`;

/** Every env's giveaway_prizes rows set to what config computes. A no-op
 *  where the table does not exist yet or a row already matches. */
export function prizeSyncSql(): string {
  const rows = PRIZES.map(
    (p) =>
      `      (${lit(p.slot)}, ${lit(prizeName(p))}, ${lit(prizeDescription(p))}, ${p.brainMap}, ${p.sessions}, ${p.vibroSessions > 0}, ${p.hoolest === "mini"}, ${p.hoolest === "veRelief"}, ${p.partners.length > 0}, ${prizeRetailUsd(p).toFixed(2)}, ${prizePractitionerCostUsd(p)}, ${prizeTaxFormRequired(p)})`
  );
  return [
    SYNC_BEGIN,
    "do $$",
    "begin",
    "  if to_regclass('public.giveaway_prizes') is null then",
    "    raise notice 'giveaway_prizes does not exist yet; apply 0010 first';",
    "    return;",
    "  end if;",
    "  update public.giveaway_prizes as g",
    "     set name = v.name, description = v.description, brain_map = v.brain_map, sessions = v.sessions, vibro_chair = v.vibro_chair,",
    "         hoolest_keychain = v.hoolest_keychain, hoolest_handheld = v.hoolest_handheld, partner_services = v.partner_services,",
    "         retail_value_usd = v.retail_value_usd, practitioner_cost_usd = v.practitioner_cost_usd, tax_form_required = v.tax_form_required",
    "    from (values",
    rows.join(",\n"),
    "    ) as v(slot, name, description, brain_map, sessions, vibro_chair, hoolest_keychain, hoolest_handheld, partner_services, retail_value_usd, practitioner_cost_usd, tax_form_required)",
    "   where g.slot = v.slot",
    "     and (g.name, g.description, g.brain_map, g.sessions, g.vibro_chair, g.hoolest_keychain, g.hoolest_handheld, g.partner_services, g.retail_value_usd, g.practitioner_cost_usd, g.tax_form_required)",
    "         is distinct from (v.name, v.description, v.brain_map, v.sessions, v.vibro_chair, v.hoolest_keychain, v.hoolest_handheld, v.partner_services, v.retail_value_usd, v.practitioner_cost_usd, v.tax_form_required);",
    "end",
    "$$;",
    SYNC_END,
  ].join("\n");
}

/** The sync block in a migration file, or null. */
export function syncBlockOf(sql: string): string | null {
  const a = sql.indexOf(SYNC_BEGIN);
  const b = sql.indexOf(SYNC_END);
  if (a < 0 || b < 0 || b < a) return null;
  return sql.slice(a, b + SYNC_END.length);
}
